'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useApp } from '@/context/AppContext';
import { 
  ShieldCheck, 
  Wrench, 
  User as UserIcon, 
  Bell, 
  LogOut, 
  Menu, 
  X, 
  LayoutDashboard,
  Sparkles,
  ChevronRight
} from 'lucide-react';

export default function Navbar() {
  const { currentUser, currentWorkerProfile, notifications, logout, markNotificationAsRead } = useApp();
  const pathname = usePathname();
  const router = useRouter();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [showNotifs, setShowNotifs] = useState(false);

  // Filter unread notifications for current user
  const userNotifications = notifications.filter(n => currentUser && n.user_id === currentUser.id);
  const unreadCount = userNotifications.filter(n => !n.is_read).length;

  const handleLogout = () => {
    logout();
    router.push('/login');
  };

  const getDashboardHref = () => {
    if (!currentUser) return '/login';
    if (currentUser.role === 'admin') return '/admin/dashboard';
    if (currentUser.role === 'worker') return '/worker/dashboard';
    return '/customer/dashboard';
  };

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 glass-panel border-b border-slate-200/60 dark:border-slate-800/80 transition-all">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 sm:h-20">
          
          {/* Logo */}
          <Link href="/" className="flex items-center gap-3 group">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-900 to-indigo-700 flex items-center justify-center text-amber-400 font-black text-2xl shadow-md group-hover:scale-105 transition-transform">
              B
            </div>
            <div className="flex flex-col">
              <span className="text-2xl font-black tracking-tight text-slate-900 dark:text-white flex items-center gap-1.5">
                BROOMESS
                <span className="text-amber-500 text-xs font-semibold px-2 py-0.5 rounded-full bg-amber-50 dark:bg-amber-950/60 border border-amber-200 dark:border-amber-800">PRO</span>
              </span>
              <span className="text-[10px] tracking-widest uppercase font-medium text-slate-500 dark:text-slate-400 -mt-1">
                Verified Services
              </span>
            </div>
          </Link>

          {/* Desktop Navigation Links */}
          <div className="hidden md:flex items-center gap-6">
            <Link 
              href="/#services" 
              className={`text-sm font-medium transition-colors hover:text-blue-900 dark:hover:text-blue-400 ${
                pathname === '/#services' ? 'text-blue-900 font-semibold' : 'text-slate-600 dark:text-slate-300'
              }`}
            >
              Services
            </Link>

            {currentUser?.role !== 'worker' && currentUser?.role !== 'admin' && (
              <Link 
                href="/login?role=worker" 
                className="text-sm font-medium text-slate-600 dark:text-slate-300 hover:text-amber-600 dark:hover:text-amber-400 transition-colors flex items-center gap-1"
              >
                <Wrench className="w-4 h-4 text-amber-500" />
                Become a Worker
              </Link>
            )}

            {/* If Logged In */}
            {currentUser ? (
              <div className="flex items-center gap-3 pl-4 border-l border-slate-200 dark:border-slate-800">
                {/* Notifications Bell */}
                <div className="relative">
                  <button 
                    onClick={() => setShowNotifs(!showNotifs)}
                    className="p-2 rounded-full text-slate-600 hover:text-blue-900 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800 relative transition-colors"
                    aria-label="Notifications"
                  >
                    <Bell className="w-5 h-5" />
                    {unreadCount > 0 && (
                      <span className="absolute top-1 right-1 w-4 h-4 bg-red-600 text-white text-[10px] font-bold rounded-full flex items-center justify-center animate-pulse">
                        {unreadCount}
                      </span>
                    )}
                  </button>

                  {/* Notifications Dropdown Drawer */}
                  {showNotifs && (
                    <div className="absolute right-0 mt-3 w-80 sm:w-96 rounded-2xl glass-panel shadow-2xl border border-slate-200 dark:border-slate-800 p-4 animate-fade-in-up z-50">
                      <div className="flex items-center justify-between pb-3 border-b border-slate-200 dark:border-slate-800">
                        <span className="font-bold text-sm text-slate-900 dark:text-white flex items-center gap-2">
                          <Bell className="w-4 h-4 text-amber-500" /> Notifications
                        </span>
                        <span className="text-xs text-slate-500">{userNotifications.length} Total</span>
                      </div>
                      
                      <div className="max-h-72 overflow-y-auto divide-y divide-slate-100 dark:divide-slate-800 mt-2">
                        {userNotifications.length === 0 ? (
                          <div className="py-6 text-center text-xs text-slate-500">
                            No notifications yet
                          </div>
                        ) : (
                          userNotifications.map((n, idx) => (
                            <div 
                              key={`${n.id}-${idx}`} 
                              onClick={() => markNotificationAsRead(n.id)}
                              className={`p-2.5 text-xs rounded-lg cursor-pointer transition-colors ${
                                n.is_read ? 'opacity-70 hover:bg-slate-50 dark:hover:bg-slate-800/40' : 'bg-blue-50/70 dark:bg-blue-950/40 font-medium'
                              }`}
                            >
                              <div className="flex justify-between items-start mb-1">
                                <span className="font-semibold text-slate-800 dark:text-slate-100">{n.title}</span>
                                <span className="text-[10px] text-slate-400">
                                  {new Date(n.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                </span>
                              </div>
                              <p className="text-slate-600 dark:text-slate-300">{n.message}</p>
                            </div>
                          ))
                        )}
                      </div>
                    </div>
                  )}
                </div>

                {/* Role Badge & Dashboard Link */}
                <Link
                  href={getDashboardHref()}
                  className="flex items-center gap-2.5 px-3.5 py-1.5 rounded-full bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                >
                  <div className="w-7 h-7 rounded-full bg-blue-900 text-white flex items-center justify-center text-xs font-bold overflow-hidden">
                    {currentWorkerProfile?.photo ? (
                      <img src={currentWorkerProfile.photo} alt="Profile" className="w-full h-full object-cover" />
                    ) : (
                      currentUser.name.charAt(0)
                    )}
                  </div>
                  <div className="flex flex-col text-left">
                    <span className="text-xs font-bold text-slate-900 dark:text-white leading-tight">
                      {currentUser.name}
                    </span>
                    <span className="text-[10px] uppercase font-semibold text-amber-600 dark:text-amber-400">
                      {currentUser.role}
                    </span>
                  </div>
                  <ChevronRight className="w-3.5 h-3.5 text-slate-400 ml-1" />
                </Link>

                {/* Logout Button */}
                <button
                  onClick={handleLogout}
                  className="p-2 rounded-full text-slate-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-950/30 transition-colors"
                  title="Log out"
                >
                  <LogOut className="w-4 h-4" />
                </button>
              </div>
            ) : (
              /* If Not Logged In */
              <div className="flex items-center gap-3">
                <Link
                  href="/login"
                  className="px-4 py-2 text-sm font-semibold text-slate-700 dark:text-slate-200 hover:text-blue-900 dark:hover:text-blue-400 transition-colors"
                >
                  Sign In
                </Link>
                <Link
                  href="/login?tab=register"
                  className="px-5 py-2.5 text-sm font-semibold text-white bg-gradient-to-r from-blue-900 to-indigo-800 hover:from-blue-950 hover:to-indigo-900 rounded-full shadow-md hover-lift transition-all flex items-center gap-1.5"
                >
                  <Sparkles className="w-4 h-4 text-amber-300" />
                  Get Started
                </Link>
              </div>
            )}
          </div>

          {/* Mobile Menu Button */}
          <div className="flex md:hidden items-center gap-2">
            {currentUser && (
              <Link 
                href={getDashboardHref()} 
                className="px-2.5 py-1 text-xs font-bold bg-blue-900 text-white rounded-full flex items-center gap-1"
              >
                <LayoutDashboard className="w-3.5 h-3.5" />
                {currentUser.role}
              </Link>
            )}
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="p-2 rounded-lg text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800"
            >
              {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu Dropdown */}
      {mobileMenuOpen && (
        <div className="md:hidden glass-panel border-b border-slate-200 dark:border-slate-800 px-4 pt-2 pb-6 space-y-3 animate-fade-in-up">
          <Link
            href="/"
            onClick={() => setMobileMenuOpen(false)}
            className="block py-2 text-sm font-medium text-slate-700 dark:text-slate-200"
          >
            Home
          </Link>
          <Link
            href="/#services"
            onClick={() => setMobileMenuOpen(false)}
            className="block py-2 text-sm font-medium text-slate-700 dark:text-slate-200"
          >
            All Services
          </Link>
          {currentUser ? (
            <>
              <Link
                href={getDashboardHref()}
                onClick={() => setMobileMenuOpen(false)}
                className="block py-2 text-sm font-bold text-blue-900 dark:text-blue-400"
              >
                Go to {currentUser.role.toUpperCase()} Dashboard
              </Link>
              <button
                onClick={() => {
                  setMobileMenuOpen(false);
                  handleLogout();
                }}
                className="w-full text-left py-2 text-sm font-semibold text-red-600 flex items-center gap-2"
              >
                <LogOut className="w-4 h-4" /> Sign Out
              </button>
            </>
          ) : (
            <div className="pt-2 flex flex-col gap-2">
              <Link
                href="/login"
                onClick={() => setMobileMenuOpen(false)}
                className="w-full py-2.5 text-center text-sm font-semibold text-slate-800 dark:text-white bg-slate-100 dark:bg-slate-800 rounded-xl"
              >
                Sign In
              </Link>
              <Link
                href="/login?tab=register"
                onClick={() => setMobileMenuOpen(false)}
                className="w-full py-2.5 text-center text-sm font-semibold text-white bg-blue-900 rounded-xl"
              >
                Register
              </Link>
            </div>
          )}
        </div>
      )}
    </nav>
  );
}
