'use client';

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { 
  User, 
  WorkerProfile, 
  WorkerLocation,
  ServiceCategory, 
  JobRequest, 
  JobStatus, 
  NotificationItem, 
  EarningRecord, 
  UserRole,
  WorkerVerificationStatus,
  WorkerAvailability,
  Review
} from '@/types';
import { 
  INITIAL_USERS, 
  INITIAL_WORKER_PROFILES, 
  INITIAL_SERVICES, 
  INITIAL_JOBS, 
  INITIAL_EARNINGS, 
  INITIAL_NOTIFICATIONS,
  INITIAL_REVIEWS
} from '@/lib/mockData';

interface AppContextType {
  currentUser: User | null;
  currentWorkerProfile: WorkerProfile | null;
  users: User[];
  workerProfiles: WorkerProfile[];
  services: ServiceCategory[];
  jobs: JobRequest[];
  notifications: NotificationItem[];
  earnings: EarningRecord[];
  reviews: Review[];
  
  // Auth methods
  login: (emailOrPhone: string, role: UserRole) => { success: boolean; message?: string; user?: User };
  register: (name: string, email: string, phone: string, role: UserRole) => { success: boolean; message?: string; user?: User };
  logout: () => void;
  
  // Worker methods
  saveWorkerProfile: (profile: Partial<WorkerProfile>) => WorkerProfile;
  setWorkerAvailability: (workerId: string, availability: WorkerAvailability) => void;
  updateWorkerLocation: (workerId: string, location: WorkerLocation) => void;
  
  // Job & Request workflow methods
  createJobRequest: (params: {
    workerId: string;
    serviceId: string;
    location: string;
    preferredTime: string;
    notes?: string;
  }) => JobRequest | null;
  updateJobStatus: (jobId: string, status: JobStatus) => void;
  
  // Admin methods
  verifyWorker: (workerProfileId: string, status: WorkerVerificationStatus) => void;
  toggleServiceStatus: (serviceId: string) => void;
  deleteWorker: (workerProfileId: string) => void;
  suspendWorker: (workerProfileId: string, days: number) => void;
  
  // Notification methods
  markNotificationAsRead: (notificationId: string) => void;
  
  // Review methods
  submitReview: (jobId: string, rating: number, comment: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export function AppProvider({ children }: { children: React.ReactNode }) {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [workerProfiles, setWorkerProfiles] = useState<WorkerProfile[]>(INITIAL_WORKER_PROFILES);
  const [services, setServices] = useState<ServiceCategory[]>(INITIAL_SERVICES);
  const [jobs, setJobs] = useState<JobRequest[]>(INITIAL_JOBS);
  const [notifications, setNotifications] = useState<NotificationItem[]>(INITIAL_NOTIFICATIONS);
  const [earnings, setEarnings] = useState<EarningRecord[]>(INITIAL_EARNINGS);
  const [reviews, setReviews] = useState<Review[]>(INITIAL_REVIEWS);
  const [isLoaded, setIsLoaded] = useState(false);

  // Load from localStorage on mount & listen for cross-tab sync
  useEffect(() => {
    try {
      const savedUser = localStorage.getItem('broomess_user');
      const savedUsers = localStorage.getItem('broomess_users_list');
      const savedWorkers = localStorage.getItem('broomess_workers_list');
      const savedJobs = localStorage.getItem('broomess_jobs_list');
      const savedNotifs = localStorage.getItem('broomess_notifs_list');
      const savedEarnings = localStorage.getItem('broomess_earnings_list');
      const savedReviews = localStorage.getItem('broomess_reviews_list');

      if (savedUser) setCurrentUser(JSON.parse(savedUser));
      if (savedUsers) setUsers(JSON.parse(savedUsers));
      if (savedWorkers) setWorkerProfiles(JSON.parse(savedWorkers));
      if (savedJobs) setJobs(JSON.parse(savedJobs));
      if (savedNotifs) setNotifications(JSON.parse(savedNotifs));
      if (savedEarnings) setEarnings(JSON.parse(savedEarnings));
      if (savedReviews) setReviews(JSON.parse(savedReviews));
    } catch (e) {
      console.error('Error loading initial data from localStorage', e);
    } finally {
      setIsLoaded(true);
    }

    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'broomess_workers_list' && e.newValue) {
        try {
          setWorkerProfiles(JSON.parse(e.newValue));
        } catch (err) {
          console.error(err);
        }
      }
      if (e.key === 'broomess_jobs_list' && e.newValue) {
        try {
          setJobs(JSON.parse(e.newValue));
        } catch (err) {
          console.error(err);
        }
      }
    };
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  // Save changes to localStorage
  useEffect(() => {
    if (!isLoaded) return;
    try {
      if (currentUser) {
        localStorage.setItem('broomess_user', JSON.stringify(currentUser));
      } else {
        localStorage.removeItem('broomess_user');
      }
      localStorage.setItem('broomess_users_list', JSON.stringify(users));
      localStorage.setItem('broomess_workers_list', JSON.stringify(workerProfiles));
      localStorage.setItem('broomess_jobs_list', JSON.stringify(jobs));
      localStorage.setItem('broomess_notifs_list', JSON.stringify(notifications));
      localStorage.setItem('broomess_earnings_list', JSON.stringify(earnings));
      localStorage.setItem('broomess_reviews_list', JSON.stringify(reviews));
    } catch (e) {
      console.error('Error saving data to localStorage', e);
    }
  }, [currentUser, users, workerProfiles, jobs, notifications, earnings, reviews, isLoaded]);

  // Derived current worker profile
  const currentWorkerProfile = currentUser?.role === 'worker' 
    ? workerProfiles.find(wp => wp.user_id === currentUser.id) || null 
    : null;

  // Login handler
  const login = (emailOrPhone: string, role: UserRole) => {
    const cleanInput = emailOrPhone.trim().toLowerCase();
    const foundUser = users.find(
      u => (u.email.toLowerCase() === cleanInput || u.phone.includes(cleanInput)) && u.role === role
    );

    if (foundUser) {
      if (foundUser.status === 'suspended') {
        let message = 'Account suspended. Please contact admin.';
        if (foundUser.suspended_until) {
          const suspendDate = new Date(foundUser.suspended_until);
          if (suspendDate > new Date()) {
            return { success: false, message: `Account is suspended until ${suspendDate.toLocaleDateString()}.` };
          } else {
            // Auto reactivate
            setUsers(prev => prev.map(u => u.id === foundUser.id ? { ...u, status: 'active', suspended_until: undefined } : u));
            foundUser.status = 'active';
            foundUser.suspended_until = undefined;
          }
        } else {
          return { success: false, message };
        }
      }

      const loggedInUser = { ...foundUser, is_online: true };
      setUsers(prev => prev.map(u => u.id === loggedInUser.id ? loggedInUser : u));
      setCurrentUser(loggedInUser);
      return { success: true, user: loggedInUser };
    }

    return { 
      success: false, 
      message: `No active ${role} account found with "${emailOrPhone}". Please check details or register.` 
    };
  };

  // Registration handler
  const register = (name: string, email: string, phone: string, role: UserRole) => {
    const existing = users.find(u => u.email.toLowerCase() === email.toLowerCase().trim() && u.role === role);
    if (existing) {
      return { success: false, message: `An account with this email already exists for ${role}.` };
    }

    const newUser: User = {
      id: `usr-${role}-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
      name: name.trim(),
      email: email.trim(),
      phone: phone.trim(),
      role,
      status: 'active',
      created_at: new Date().toISOString(),
      is_online: true
    };

    const updatedUsers = [...users, newUser];
    setUsers(updatedUsers);
    setCurrentUser(newUser);

    // If registering as worker, create blank draft profile
    if (role === 'worker') {
      const generatedWorkerId = `BRM-W${Math.floor(100 + Math.random() * 900)}`;
      const newProfile: WorkerProfile = {
        id: `wp-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
        user_id: newUser.id,
        worker_id: generatedWorkerId,
        name: newUser.name,
        phone: newUser.phone,
        email: newUser.email,
        work_type: '',
        experience: '1 Year',
        fee: 300,
        service_area: '',
        availability: 'available',
        verification_status: 'pending',
        rating: 5.0,
        total_reviews: 0,
        description: '',
        created_at: new Date().toISOString()
      };
      setWorkerProfiles(prev => [...prev, newProfile]);
    }

    return { success: true, user: newUser };
  };

  const logout = () => {
    if (currentUser) {
      setUsers(prev => prev.map(u => u.id === currentUser.id ? { ...u, is_online: false } : u));
    }
    setCurrentUser(null);
  };

  // Worker profile update
  const saveWorkerProfile = (profileData: Partial<WorkerProfile>) => {
    if (!currentUser) throw new Error('No authenticated user');

    let existingProfile = workerProfiles.find(wp => wp.user_id === currentUser.id);
    let updatedProfile: WorkerProfile;

    if (existingProfile) {
      updatedProfile = {
        ...existingProfile,
        ...profileData,
        name: currentUser.name,
        email: currentUser.email,
        phone: currentUser.phone
      };
      setWorkerProfiles(prev => prev.map(wp => wp.id === existingProfile!.id ? updatedProfile : wp));
    } else {
      const generatedWorkerId = `BRM-W${Math.floor(100 + Math.random() * 900)}`;
      updatedProfile = {
        id: `wp-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
        user_id: currentUser.id,
        worker_id: generatedWorkerId,
        name: currentUser.name,
        email: currentUser.email,
        phone: currentUser.phone,
        work_type: profileData.work_type || 'General Service',
        experience: profileData.experience || '1 Year',
        fee: profileData.fee || 350,
        service_area: profileData.service_area || 'Delhi NCR',
        availability: profileData.availability || 'available',
        verification_status: 'pending',
        rating: 5.0,
        total_reviews: 0,
        description: profileData.description || '',
        created_at: new Date().toISOString(),
        ...profileData
      };
      setWorkerProfiles(prev => [...prev, updatedProfile]);
    }

    return updatedProfile;
  };

  const setWorkerAvailability = (workerId: string, availability: WorkerAvailability) => {
    setWorkerProfiles(prev => prev.map(w => {
      if (w.id === workerId || w.worker_id === workerId || w.user_id === workerId) {
        return { ...w, availability };
      }
      return w;
    }));
  };

  const updateWorkerLocation = useCallback((workerId: string, location: WorkerLocation) => {
    setWorkerProfiles(prev => prev.map(w => {
      if (w.id === workerId || w.worker_id === workerId || w.user_id === workerId) {
        return { ...w, location, is_location_enabled: true };
      }
      return w;
    }));

    setJobs(prev => prev.map(job => {
      if (job.worker_id === workerId || job.worker_name === workerId) {
        return { ...job, worker_location: location };
      }
      return job;
    }));
  }, []);

  // Job creation workflow (Customer sends job to exact worker)
  const createJobRequest = ({
    workerId,
    serviceId,
    location,
    preferredTime,
    notes
  }: {
    workerId: string;
    serviceId: string;
    location: string;
    preferredTime: string;
    notes?: string;
  }) => {
    if (!currentUser) return null;

    const worker = workerProfiles.find(w => w.id === workerId || w.worker_id === workerId);
    const service = services.find(s => s.id === serviceId);

    if (!worker || !service) return null;

    const newJob: JobRequest = {
      id: `job-${Date.now().toString().slice(-4)}`,
      customer_id: currentUser.id,
      customer_name: currentUser.name,
      customer_phone: currentUser.phone,
      worker_id: worker.id,
      worker_name: worker.name,
      service_id: service.id,
      service_name: service.name,
      location,
      preferred_time: preferredTime,
      fee: worker.fee || service.base_price,
      status: 'NOTIFIED',
      notes: notes || '',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };

    setJobs(prev => [newJob, ...prev]);

    // Send in-app notification directly to worker
    const workerNotification: NotificationItem = {
      id: `notif-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
      user_id: worker.user_id,
      request_id: newJob.id,
      title: `⚡ New Job Request: ${service.name}`,
      message: `${currentUser.name} requested ${service.name} at ${location} for ${preferredTime}. Fee: ₹${newJob.fee}`,
      type: 'job_request',
      is_read: false,
      created_at: new Date().toISOString()
    };

    setNotifications(prev => [workerNotification, ...prev]);

    return newJob;
  };

  // Job status transitions
  const updateJobStatus = (jobId: string, status: JobStatus) => {
    setJobs(prev => prev.map(job => {
      if (job.id === jobId) {
        const updated = { ...job, status, updated_at: new Date().toISOString() };

        // Handle notifications based on status
        if (status === 'ACCEPTED') {
          setNotifications(n => [
            {
              id: `notif-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
              user_id: job.customer_id,
              request_id: job.id,
              title: '✅ Request Accepted!',
              message: `${job.worker_name} has accepted your request for ${job.service_name}.`,
              type: 'status_update',
              is_read: false,
              created_at: new Date().toISOString()
            },
            ...n
          ]);
        } else if (status === 'COMPLETED') {
          // Automatic earnings record creation
          const newEarning: EarningRecord = {
            id: `earn-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
            worker_id: job.worker_id,
            request_id: job.id,
            amount: job.fee,
            service_name: job.service_name,
            customer_name: job.customer_name,
            status: 'paid',
            created_at: new Date().toISOString()
          };
          setEarnings(e => [newEarning, ...e]);

          // Customer completion notification
          setNotifications(n => [
            {
              id: `notif-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
              user_id: job.customer_id,
              request_id: job.id,
              title: '🎉 Service Completed',
              message: `${job.worker_name} has completed the service: ${job.service_name}. Total paid: ₹${job.fee}. Please leave a rating!`,
              type: 'status_update',
              is_read: false,
              created_at: new Date().toISOString()
            },
            ...n
          ]);
        }

        return updated;
      }
      return job;
    }));
  };

  // Admin worker verification
  const verifyWorker = (workerProfileId: string, status: WorkerVerificationStatus) => {
    setWorkerProfiles(prev => prev.map(w => {
      if (w.id === workerProfileId) {
        // Send notification to worker
        setNotifications(n => [
          {
            id: `notif-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
            user_id: w.user_id,
            title: status === 'verified' ? '🎉 Profile Verified!' : '⚠️ Profile Verification Update',
            message: status === 'verified' 
              ? 'Congratulations! Your profile has been verified by the Broomess Admin team. You can now accept customer requests.' 
              : 'Your profile verification status has been updated to: ' + status,
            type: 'verification',
            is_read: false,
            created_at: new Date().toISOString()
          },
          ...n
        ]);

        return { ...w, verification_status: status };
      }
      return w;
    }));
  };

  const toggleServiceStatus = (serviceId: string) => {
    setServices(prev => prev.map(s => s.id === serviceId ? { ...s, active: !s.active } : s));
  };

  const deleteWorker = (workerProfileId: string) => {
    const workerProfile = workerProfiles.find(w => w.id === workerProfileId);
    if (!workerProfile) return;
    
    // Remove worker profile
    setWorkerProfiles(prev => prev.filter(w => w.id !== workerProfileId));
    
    // Also remove the user account
    setUsers(prev => prev.filter(u => u.id !== workerProfile.user_id));
  };

  const suspendWorker = (workerProfileId: string, days: number) => {
    const workerProfile = workerProfiles.find(w => w.id === workerProfileId);
    if (!workerProfile) return;

    // Calculate suspension end date
    const suspendUntil = new Date();
    suspendUntil.setDate(suspendUntil.getDate() + days);

    // Update user status
    setUsers(prev => prev.map(u => {
      if (u.id === workerProfile.user_id) {
        return { 
          ...u, 
          status: 'suspended',
          suspended_until: suspendUntil.toISOString()
        };
      }
      return u;
    }));
  };

  const markNotificationAsRead = (notificationId: string) => {
    setNotifications(prev => prev.map(n => n.id === notificationId ? { ...n, is_read: true } : n));
  };

  const submitReview = (jobId: string, rating: number, comment: string) => {
    const job = jobs.find(j => j.id === jobId);
    if (!job || !currentUser) return;

    const newReview: Review = {
      id: `rev-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
      request_id: job.id,
      customer_id: currentUser.id,
      customer_name: currentUser.name,
      worker_id: job.worker_id,
      rating,
      comment,
      created_at: new Date().toISOString()
    };

    setReviews(prev => [newReview, ...prev]);

    // Update worker rating
    setWorkerProfiles(prev => prev.map(worker => {
      if (worker.id === job.worker_id) {
        const totalOldRatingPoints = worker.rating * worker.total_reviews;
        const newTotalReviews = worker.total_reviews + 1;
        const avgRating = (totalOldRatingPoints + rating) / newTotalReviews;
        
        return {
          ...worker,
          rating: avgRating,
          total_reviews: newTotalReviews
        };
      }
      return worker;
    }));
  };

  return (
    <AppContext.Provider
      value={{
        currentUser,
        currentWorkerProfile,
        users,
        workerProfiles,
        services,
        jobs,
        notifications,
        earnings,
        reviews,
        login,
        register,
        logout,
        saveWorkerProfile,
        setWorkerAvailability,
        updateWorkerLocation,
        createJobRequest,
        updateJobStatus,
        verifyWorker,
        toggleServiceStatus,
        deleteWorker,
        suspendWorker,
        markNotificationAsRead,
        submitReview
      }}
    >
      {children}
    </AppContext.Provider>
  );
}

export function useApp() {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
}
